```yaml
name: Merge Queue Cleanup

on:
  schedule:
    - cron: '*/5 * * * *'
  workflow_dispatch:

jobs:
  cleanup:
    runs-on: ubuntu-latest
    permissions:
      pull-requests: write
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Auto-dequeue unmergeable PRs
        uses: actions/github-script@v6
        with:
          script: |
            const data = await github.graphql(`
              query {
                repository(owner: "${context.repo.owner}", name: "${context.repo.repo}") {
                  id
                  mergeQueueEntries(first: 100) {
                    nodes {
                      id
                      state
                      pullRequest {
                        number
                        title
                        author {
                          login
                        }
                      }
                    }
                  }
                }
              }
            `);

            const unmergeable = data.repository.mergeQueueEntries.nodes.filter(
              e => e.state === 'UNMERGEABLE'
            );

            for (const entry of unmergeable) {
              const prNumber = entry.pullRequest.number;

              await github.graphql(`
                mutation($repoId: ID!, $prNumber: Int!) {
                  removeMergeQueueEntry(input: {repositoryId: $repoId, pullRequestNumber: $prNumber}) {
                    clientMutationId
                  }
                }
              `, {
                repoId: data.repository.id,
                prNumber: prNumber
              });

              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: prNumber,
                body: `This PR was removed from the merge queue because it was marked as \`UNMERGEABLE\`. Please rebase and re-open the PR to re-enter the queue.`
              });
            }
```

